import gurobipy as gp
from gurobipy import GRB
areas = []
value = {}
weight = {}
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        name = rec['values']['ProductName']
        areas.append(name)
        value[name] = int(rec['values']['Value'])
        weight[name] = int(rec['values']['Weight'])
    elif rec['source'] == 'capacity.csv':
        capacity = int(rec['values']['Capacity'])
if set(value.keys()) != set(areas) or set(weight.keys()) != set(areas):
    raise ValueError('Missing value or weight data for some areas.')
if capacity is None:
    raise ValueError('Missing capacity data.')
m = gp.Model('NY_Development')
x = m.addVars(areas, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((value[i] * x[i] for i in areas)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in areas)) <= capacity, name='cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')